use pulldown_cmark::{Options, Parser, html};

fn render(input: &str, subscript: bool, strikethrough: bool) -> String {
    let mut opts = Options::empty();
    if subscript { opts.insert(Options::ENABLE_SUBSCRIPT); }
    if strikethrough { opts.insert(Options::ENABLE_STRIKETHROUGH); }
    let mut s = String::new();
    html::push_html(&mut s, Parser::new_ext(input, opts));
    s
}

fn main() {
    let cases = [
        "~~This ~is~~ stricken.~",
        "a ~[x](https://x)~",
        "b ~~[x](https://x)~~",
        "d ~~x ~[x](https://x)~ x~~",
    ];
    for c in cases {
        println!("{:?} -> {}", c, render(c, true, false));
    }
}
EOF
